export const DATA = {"hero":[{"kind":"html","text":"<div class=\"hero\">\n          <div class=\"kicker\">ORDER-TO-CASH SQL REASONING</div>\n          <h1>Gem City SQL Investigation</h1>\n          <p>Read the query, locate the reporting failure, repair the logic, and write a defensible accounting or audit report.</p>\n        </div>"}],"stages":["Brief","1. Read","2. Missing rows","3. Wrong amount","4. Write","Complete"],"screens":[{"unanswered":[{"kind":"html","text":"<div class=\"eyebrow\">Investigation briefing</div>"},{"kind":"header","text":"Turn Gem City Office Supply data into useful accounting information"},{"kind":"markdown","text":"Gem City Office Supply sells office furnishings to business customers. Its order-to-cash information is stored in a normalized database, with related business facts separated into connected tables."},{"kind":"html","text":"<div class=\"case-card\"><strong>Your investigation</strong> You will interpret existing SQL, diagnose why plausible queries produce incomplete or misleading results, and then build both an accounting report and an audit exception report. The goal is to connect query logic to the accounting purpose the output must serve.</div>"},{"kind":"button","label":"Begin reading SQL","key":null}],"wrong":[{"kind":"html","text":"<div class=\"eyebrow\">Investigation briefing</div>"},{"kind":"header","text":"Turn Gem City Office Supply data into useful accounting information"},{"kind":"markdown","text":"Gem City Office Supply sells office furnishings to business customers. Its order-to-cash information is stored in a normalized database, with related business facts separated into connected tables."},{"kind":"html","text":"<div class=\"case-card\"><strong>Your investigation</strong> You will interpret existing SQL, diagnose why plausible queries produce incomplete or misleading results, and then build both an accounting report and an audit exception report. The goal is to connect query logic to the accounting purpose the output must serve.</div>"},{"kind":"button","label":"Begin reading SQL","key":null}],"correct":[{"kind":"html","text":"<div class=\"eyebrow\">Investigation briefing</div>"},{"kind":"header","text":"Turn Gem City Office Supply data into useful accounting information"},{"kind":"markdown","text":"Gem City Office Supply sells office furnishings to business customers. Its order-to-cash information is stored in a normalized database, with related business facts separated into connected tables."},{"kind":"html","text":"<div class=\"case-card\"><strong>Your investigation</strong> You will interpret existing SQL, diagnose why plausible queries produce incomplete or misleading results, and then build both an accounting report and an audit exception report. The goal is to connect query logic to the accounting purpose the output must serve.</div>"},{"kind":"button","label":"Begin reading SQL","key":null}]},{"unanswered":[{"kind":"html","text":"<div class=\"eyebrow\">Step 1</div>"},{"kind":"header","text":"Read the query in logical order"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Trace what the database must do with the query. SQL begins with SELECT when written, but the database must establish the row sources and joins before it can filter rows and shape the final output.</p>"},{"kind":"code","text":"SELECT c.CustomerName,\n       o.OrderID,\n       ol.Quantity * ol.ActualUnitPrice AS LineAmount\nFROM Customers AS c\nJOIN Orders AS o\n  ON o.CustomerID = c.CustomerID\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nWHERE o.OrderStatus = 'Fulfilled'\nORDER BY c.CustomerName, o.OrderID;"},{"kind":"radio","label":"Which clauses assemble the rows before filtering?","options":["ORDER BY","SELECT","WHERE","FROM and JOIN"],"key":"widget_si_read_source","help":null},{"kind":"radio","label":"Which part determines the columns displayed in the result?","options":["ON","SELECT expressions","FROM","WHERE"],"key":"widget_si_read_output","help":null},{"kind":"radio","label":"Which clause removes rows that do not satisfy the reporting condition?","options":["GROUP BY","ON","WHERE","SELECT"],"key":"widget_si_read_filter","help":null},{"kind":"button","label":"Check how the query works","key":null}],"wrong":[{"kind":"html","text":"<div class=\"eyebrow\">Step 1</div>"},{"kind":"header","text":"Read the query in logical order"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Trace what the database must do with the query. SQL begins with SELECT when written, but the database must establish the row sources and joins before it can filter rows and shape the final output.</p>"},{"kind":"code","text":"SELECT c.CustomerName,\n       o.OrderID,\n       ol.Quantity * ol.ActualUnitPrice AS LineAmount\nFROM Customers AS c\nJOIN Orders AS o\n  ON o.CustomerID = c.CustomerID\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nWHERE o.OrderStatus = 'Fulfilled'\nORDER BY c.CustomerName, o.OrderID;"},{"kind":"info","text":"Revise any answer below, then select Check revised answers."},{"kind":"radio","label":"Which clauses assemble the rows before filtering?","options":["ORDER BY","SELECT","WHERE","FROM and JOIN"],"key":"widget_si_read_source","help":null},{"kind":"radio","label":"Which part determines the columns displayed in the result?","options":["ON","SELECT expressions","FROM","WHERE"],"key":"widget_si_read_output","help":null},{"kind":"radio","label":"Which clause removes rows that do not satisfy the reporting condition?","options":["GROUP BY","ON","WHERE","SELECT"],"key":"widget_si_read_filter","help":null},{"kind":"button","label":"Check revised answers","key":null},{"kind":"html","text":"<div class=\"feedback \"><strong>Which clauses assemble the rows before filtering? — Reconsider.</strong> Your answer: SELECT. Hint: Separate the written order from the database&#x27;s logical work. Which clauses identify the starting rows and connect related tables before filtering?</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Which part determines the columns displayed in the result? — Correct.</strong> Your answer: SELECT expressions. SELECT appears first in the written query, but it describes the final output columns.</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Which clause removes rows that do not satisfy the reporting condition? — Correct.</strong> Your answer: WHERE. WHERE evaluates the condition after the row sources and joins have been established.</div>"}],"correct":[{"kind":"html","text":"<div class=\"eyebrow\">Step 1</div>"},{"kind":"header","text":"Read the query in logical order"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Trace what the database must do with the query. SQL begins with SELECT when written, but the database must establish the row sources and joins before it can filter rows and shape the final output.</p>"},{"kind":"code","text":"SELECT c.CustomerName,\n       o.OrderID,\n       ol.Quantity * ol.ActualUnitPrice AS LineAmount\nFROM Customers AS c\nJOIN Orders AS o\n  ON o.CustomerID = c.CustomerID\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nWHERE o.OrderStatus = 'Fulfilled'\nORDER BY c.CustomerName, o.OrderID;"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Which clauses assemble the rows before filtering? — Correct.</strong> Your answer: FROM and JOIN. FROM identifies the starting table, and JOIN adds matching rows from related tables.</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Which part determines the columns displayed in the result? — Correct.</strong> Your answer: SELECT expressions. SELECT appears first in the written query, but it describes the final output columns.</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Which clause removes rows that do not satisfy the reporting condition? — Correct.</strong> Your answer: WHERE. WHERE evaluates the condition after the row sources and joins have been established.</div>"},{"kind":"button","label":"Continue to the missing-record case","key":null}]},{"unanswered":[{"kind":"html","text":"<div class=\"eyebrow\">Step 2</div>"},{"kind":"header","text":"Find why the unpaid-order report returns nothing"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the repair that preserves the records the controller needs, then select the explanation that supports your repair.</p>"},{"kind":"markdown","text":"The controller expects the report to list orders with no payment record. The current query returns zero rows even though two orders have no related payment."},{"kind":"code","text":"SELECT o.OrderID, c.CustomerName\nFROM Orders AS o\nJOIN Customers AS c\n  ON c.CustomerID = o.CustomerID\nINNER JOIN Payments AS p\n  ON p.OrderID = o.OrderID\nWHERE p.PaymentID IS NULL;"},{"kind":"radio","label":"1. Which repair matches the reporting purpose?","options":["Delete the WHERE clause","Replace INNER JOIN Payments with CROSS JOIN Payments","Change IS NULL to IS NOT NULL","Replace INNER JOIN Payments with LEFT JOIN Payments and keep WHERE p.PaymentID IS NULL"],"key":"widget_si_missing_repair","help":null},{"kind":"radio","label":"2. Which explanation best supports that repair?","options":["Testing IS NOT NULL retains the orders that have no matching payment record","A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test","A CROSS JOIN creates unmatched payment rows with NULL identifiers for each unpaid order","Deleting WHERE is appropriate because the INNER JOIN already isolates orders without payments"],"key":"widget_si_missing_cause","help":null},{"kind":"button","label":"Diagnose the missing rows","key":null}],"wrong":[{"kind":"html","text":"<div class=\"eyebrow\">Step 2</div>"},{"kind":"header","text":"Find why the unpaid-order report returns nothing"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the repair that preserves the records the controller needs, then select the explanation that supports your repair.</p>"},{"kind":"markdown","text":"The controller expects the report to list orders with no payment record. The current query returns zero rows even though two orders have no related payment."},{"kind":"code","text":"SELECT o.OrderID, c.CustomerName\nFROM Orders AS o\nJOIN Customers AS c\n  ON c.CustomerID = o.CustomerID\nINNER JOIN Payments AS p\n  ON p.OrderID = o.OrderID\nWHERE p.PaymentID IS NULL;"},{"kind":"info","text":"Revise either answer below, then select Check revised answers."},{"kind":"radio","label":"1. Which repair matches the reporting purpose?","options":["Delete the WHERE clause","Replace INNER JOIN Payments with CROSS JOIN Payments","Change IS NULL to IS NOT NULL","Replace INNER JOIN Payments with LEFT JOIN Payments and keep WHERE p.PaymentID IS NULL"],"key":"widget_si_missing_repair","help":null},{"kind":"radio","label":"2. Which explanation best supports that repair?","options":["Testing IS NOT NULL retains the orders that have no matching payment record","A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test","A CROSS JOIN creates unmatched payment rows with NULL identifiers for each unpaid order","Deleting WHERE is appropriate because the INNER JOIN already isolates orders without payments"],"key":"widget_si_missing_cause","help":null},{"kind":"button","label":"Check revised answers","key":null},{"kind":"html","text":"<div class=\"feedback \"><strong>How to repair the query — Reconsider.</strong> Your answer: Delete the WHERE clause. Hint: The report still needs a test that isolates missing matches, so removing the filter cannot identify unpaid orders. Focus on preserving unmatched orders before that test runs.</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Why that repair works — Correct.</strong> Your answer: A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test. The original inner join kept only orders that already had a payment match, so no surviving row could have a NULL PaymentID.</div>"}],"correct":[{"kind":"html","text":"<div class=\"eyebrow\">Step 2</div>"},{"kind":"header","text":"Find why the unpaid-order report returns nothing"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the repair that preserves the records the controller needs, then select the explanation that supports your repair.</p>"},{"kind":"markdown","text":"The controller expects the report to list orders with no payment record. The current query returns zero rows even though two orders have no related payment."},{"kind":"code","text":"SELECT o.OrderID, c.CustomerName\nFROM Orders AS o\nJOIN Customers AS c\n  ON c.CustomerID = o.CustomerID\nINNER JOIN Payments AS p\n  ON p.OrderID = o.OrderID\nWHERE p.PaymentID IS NULL;"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>How to repair the query — Correct.</strong> Your answer: Replace INNER JOIN Payments with LEFT JOIN Payments and keep WHERE p.PaymentID IS NULL. A left join keeps every order, and unmatched payment columns become NULL for the WHERE test.</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Why that repair works — Correct.</strong> Your answer: A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test. The original inner join kept only orders that already had a payment match, so no surviving row could have a NULL PaymentID.</div>"},{"kind":"subheader","text":"Repaired query and result"},{"kind":"code","text":"SELECT o.OrderID, c.CustomerName\nFROM Orders AS o\nJOIN Customers AS c\n  ON c.CustomerID = o.CustomerID\nLEFT JOIN Payments AS p\n  ON p.OrderID = o.OrderID\nWHERE p.PaymentID IS NULL\nORDER BY o.OrderID;"},{"kind":"table","rows":[{"OrderID":"O5003","CustomerName":"Blue Ridge Design"},{"OrderID":"O5004","CustomerName":"Riverbend Health"}]},{"kind":"html","text":"<div class=\"principle\"><strong>Accounting interpretation</strong> No payment row means no payment record in this database. It does not prove the customer owes the full order amount unless the system also records partial payments, credits, write-offs, and timing consistently.</div>"},{"kind":"button","label":"Continue to the wrong-amount case","key":null}]},{"unanswered":[{"kind":"html","text":"<div class=\"eyebrow\">Step 3</div>"},{"kind":"header","text":"Find why the sales amount is overstated"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the value that measures the historical exchange, then select the explanation that supports your choice.</p>"},{"kind":"markdown","text":"The query runs and every order appears, but discounted lines are valued at the standard price instead of the price the customer actually paid."},{"kind":"code","text":"SELECT o.OrderID,\n       SUM(ol.Quantity * p.StandardPrice) AS ReportedSales\nFROM Orders AS o\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nJOIN Products AS p\n  ON p.ProductID = ol.ProductID\nGROUP BY o.OrderID\nORDER BY o.OrderID;"},{"kind":"radio","label":"1. Which value should be multiplied by ol.Quantity in the ReportedSales expression?","options":["ol.ActualUnitPrice","ol.Quantity","p.StandardPrice * 0.90","p.StandardPrice"],"key":"widget_si_amount_field","help":null},{"kind":"radio","label":"2. Which explanation best supports that choice?","options":["p.StandardPrice is master data, so it always equals the price charged on every historical order line","Multiplying p.StandardPrice by 0.90 reliably reconstructs every discount without using the stored transaction price","ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line","ol.Quantity alone represents sales because the related product table already contains a price"],"key":"widget_si_amount_cause","help":null},{"kind":"button","label":"Diagnose the amount","key":null}],"wrong":[{"kind":"html","text":"<div class=\"eyebrow\">Step 3</div>"},{"kind":"header","text":"Find why the sales amount is overstated"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the value that measures the historical exchange, then select the explanation that supports your choice.</p>"},{"kind":"markdown","text":"The query runs and every order appears, but discounted lines are valued at the standard price instead of the price the customer actually paid."},{"kind":"code","text":"SELECT o.OrderID,\n       SUM(ol.Quantity * p.StandardPrice) AS ReportedSales\nFROM Orders AS o\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nJOIN Products AS p\n  ON p.ProductID = ol.ProductID\nGROUP BY o.OrderID\nORDER BY o.OrderID;"},{"kind":"info","text":"Revise either answer below, then select Check revised answers."},{"kind":"radio","label":"1. Which value should be multiplied by ol.Quantity in the ReportedSales expression?","options":["ol.ActualUnitPrice","ol.Quantity","p.StandardPrice * 0.90","p.StandardPrice"],"key":"widget_si_amount_field","help":null},{"kind":"radio","label":"2. Which explanation best supports that choice?","options":["p.StandardPrice is master data, so it always equals the price charged on every historical order line","Multiplying p.StandardPrice by 0.90 reliably reconstructs every discount without using the stored transaction price","ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line","ol.Quantity alone represents sales because the related product table already contains a price"],"key":"widget_si_amount_cause","help":null},{"kind":"button","label":"Check revised answers","key":null},{"kind":"html","text":"<div class=\"feedback \"><strong>Which field belongs in sales — Reconsider.</strong> Your answer: p.StandardPrice. Hint: Distinguish a product benchmark from the amount recorded on the individual order line.</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Why that field is appropriate — Correct.</strong> Your answer: ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line. StandardPrice is current master data and remains useful as a benchmark, but it does not prove what the customer was charged on an earlier transaction.</div>"}],"correct":[{"kind":"html","text":"<div class=\"eyebrow\">Step 3</div>"},{"kind":"header","text":"Find why the sales amount is overstated"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the value that measures the historical exchange, then select the explanation that supports your choice.</p>"},{"kind":"markdown","text":"The query runs and every order appears, but discounted lines are valued at the standard price instead of the price the customer actually paid."},{"kind":"code","text":"SELECT o.OrderID,\n       SUM(ol.Quantity * p.StandardPrice) AS ReportedSales\nFROM Orders AS o\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nJOIN Products AS p\n  ON p.ProductID = ol.ProductID\nGROUP BY o.OrderID\nORDER BY o.OrderID;"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Which field belongs in sales — Correct.</strong> Your answer: ol.ActualUnitPrice. ActualUnitPrice is stored on each line because it is a historical transaction fact.</div>"},{"kind":"html","text":"<div class=\"feedback correct\"><strong>Why that field is appropriate — Correct.</strong> Your answer: ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line. StandardPrice is current master data and remains useful as a benchmark, but it does not prove what the customer was charged on an earlier transaction.</div>"},{"kind":"html","text":"<div class=\"principle\"><strong>Correct measure</strong> Sales for each line are ol.Quantity × ol.ActualUnitPrice. p.StandardPrice remains useful for exception testing, but it is not the recorded exchange amount.</div>"},{"kind":"button","label":"Continue to the custom query","key":null}]},{"unanswered":[{"kind":"html","text":"<div class=\"eyebrow\">Step 4</div>"},{"kind":"header","text":"Build two queries for two accounting purposes"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Write both queries below. Each editor is checked independently, and any executable query will display its output so you can compare the result with the stated purpose and revise.</p>"},{"kind":"subheader","text":"Available tables and fields"},{"kind":"html","text":"<div class=\"schema-key\"><span>CustomerID</span> Primary key field</div><div class=\"schema-grid\"><section class=\"schema-table\"><h4>Customers</h4><div class=\"schema-field primary-key\">CustomerID</div><div class=\"schema-field\">CustomerName</div><div class=\"schema-field\">CustomerCity</div></section><section class=\"schema-table\"><h4>Orders</h4><div class=\"schema-field primary-key\">OrderID</div><div class=\"schema-field\">OrderDate</div><div class=\"schema-field\">CustomerID</div><div class=\"schema-field\">OrderStatus</div></section><section class=\"schema-table\"><h4>Products</h4><div class=\"schema-field primary-key\">ProductID</div><div class=\"schema-field\">ProductName</div><div class=\"schema-field\">StandardPrice</div></section><section class=\"schema-table\"><h4>OrderLines</h4><div class=\"schema-field primary-key\">OrderLineID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">ProductID</div><div class=\"schema-field\">Quantity</div><div class=\"schema-field\">ActualUnitPrice</div></section><section class=\"schema-table\"><h4>Payments</h4><div class=\"schema-field primary-key\">PaymentID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">PaymentDate</div><div class=\"schema-field\">Amount</div></section></div>"},{"kind":"subheader","text":"1. Accounting report"},{"kind":"html","text":"<div class=\"purpose\"><strong>Purpose</strong> Calculate total fulfilled-order sales by customer using the historical price charged.<br><strong>Required output</strong> Return exactly these aliases: CustomerName and TotalSales. Include every customer with fulfilled orders.</div>"},{"kind":"textarea","label":"Accounting report SQL","key":"widget_si_accounting_sql"},{"kind":"button","label":"Check accounting report","key":"check_si_accounting"},{"kind":"subheader","text":"2. Audit exception report"},{"kind":"html","text":"<div class=\"purpose\"><strong>Purpose</strong> Identify order lines sold more than 10 percent below the product&#x27;s standard price.<br><strong>Required output</strong> Return these aliases: OrderLineID, OrderID, ProductName, ActualUnitPrice, StandardPrice, and DiscountPct.</div>"},{"kind":"textarea","label":"Audit exception report SQL","key":"widget_si_audit_sql"},{"kind":"button","label":"Check audit exception report","key":"check_si_audit"}],"wrong":[{"kind":"html","text":"<div class=\"eyebrow\">Step 4</div>"},{"kind":"header","text":"Build two queries for two accounting purposes"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Write both queries below. Each editor is checked independently, and any executable query will display its output so you can compare the result with the stated purpose and revise.</p>"},{"kind":"subheader","text":"Available tables and fields"},{"kind":"html","text":"<div class=\"schema-key\"><span>CustomerID</span> Primary key field</div><div class=\"schema-grid\"><section class=\"schema-table\"><h4>Customers</h4><div class=\"schema-field primary-key\">CustomerID</div><div class=\"schema-field\">CustomerName</div><div class=\"schema-field\">CustomerCity</div></section><section class=\"schema-table\"><h4>Orders</h4><div class=\"schema-field primary-key\">OrderID</div><div class=\"schema-field\">OrderDate</div><div class=\"schema-field\">CustomerID</div><div class=\"schema-field\">OrderStatus</div></section><section class=\"schema-table\"><h4>Products</h4><div class=\"schema-field primary-key\">ProductID</div><div class=\"schema-field\">ProductName</div><div class=\"schema-field\">StandardPrice</div></section><section class=\"schema-table\"><h4>OrderLines</h4><div class=\"schema-field primary-key\">OrderLineID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">ProductID</div><div class=\"schema-field\">Quantity</div><div class=\"schema-field\">ActualUnitPrice</div></section><section class=\"schema-table\"><h4>Payments</h4><div class=\"schema-field primary-key\">PaymentID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">PaymentDate</div><div class=\"schema-field\">Amount</div></section></div>"},{"kind":"subheader","text":"1. Accounting report"},{"kind":"html","text":"<div class=\"purpose\"><strong>Purpose</strong> Calculate total fulfilled-order sales by customer using the historical price charged.<br><strong>Required output</strong> Return exactly these aliases: CustomerName and TotalSales. Include every customer with fulfilled orders.</div>"},{"kind":"textarea","label":"Accounting report SQL","key":"widget_si_accounting_sql"},{"kind":"button","label":"Check accounting report","key":"check_si_accounting"},{"kind":"subheader","text":"2. Audit exception report"},{"kind":"html","text":"<div class=\"purpose\"><strong>Purpose</strong> Identify order lines sold more than 10 percent below the product&#x27;s standard price.<br><strong>Required output</strong> Return these aliases: OrderLineID, OrderID, ProductName, ActualUnitPrice, StandardPrice, and DiscountPct.</div>"},{"kind":"textarea","label":"Audit exception report SQL","key":"widget_si_audit_sql"},{"kind":"button","label":"Check audit exception report","key":"check_si_audit"}],"correct":[{"kind":"html","text":"<div class=\"eyebrow\">Step 4</div>"},{"kind":"header","text":"Build two queries for two accounting purposes"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Write both queries below. Each editor is checked independently, and any executable query will display its output so you can compare the result with the stated purpose and revise.</p>"},{"kind":"subheader","text":"Available tables and fields"},{"kind":"html","text":"<div class=\"schema-key\"><span>CustomerID</span> Primary key field</div><div class=\"schema-grid\"><section class=\"schema-table\"><h4>Customers</h4><div class=\"schema-field primary-key\">CustomerID</div><div class=\"schema-field\">CustomerName</div><div class=\"schema-field\">CustomerCity</div></section><section class=\"schema-table\"><h4>Orders</h4><div class=\"schema-field primary-key\">OrderID</div><div class=\"schema-field\">OrderDate</div><div class=\"schema-field\">CustomerID</div><div class=\"schema-field\">OrderStatus</div></section><section class=\"schema-table\"><h4>Products</h4><div class=\"schema-field primary-key\">ProductID</div><div class=\"schema-field\">ProductName</div><div class=\"schema-field\">StandardPrice</div></section><section class=\"schema-table\"><h4>OrderLines</h4><div class=\"schema-field primary-key\">OrderLineID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">ProductID</div><div class=\"schema-field\">Quantity</div><div class=\"schema-field\">ActualUnitPrice</div></section><section class=\"schema-table\"><h4>Payments</h4><div class=\"schema-field primary-key\">PaymentID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">PaymentDate</div><div class=\"schema-field\">Amount</div></section></div>"},{"kind":"subheader","text":"1. Accounting report"},{"kind":"html","text":"<div class=\"purpose\"><strong>Purpose</strong> Calculate total fulfilled-order sales by customer using the historical price charged.<br><strong>Required output</strong> Return exactly these aliases: CustomerName and TotalSales. Include every customer with fulfilled orders.</div>"},{"kind":"textarea","label":"Accounting report SQL","key":"widget_si_accounting_sql"},{"kind":"button","label":"Check accounting report","key":"check_si_accounting"},{"kind":"subheader","text":"2. Audit exception report"},{"kind":"html","text":"<div class=\"purpose\"><strong>Purpose</strong> Identify order lines sold more than 10 percent below the product&#x27;s standard price.<br><strong>Required output</strong> Return these aliases: OrderLineID, OrderID, ProductName, ActualUnitPrice, StandardPrice, and DiscountPct.</div>"},{"kind":"textarea","label":"Audit exception report SQL","key":"widget_si_audit_sql"},{"kind":"button","label":"Check audit exception report","key":"check_si_audit"}]},{"unanswered":[{"kind":"html","text":"<div class=\"eyebrow\">Investigation complete</div>"},{"kind":"header","text":"A correct query must match both the database structure and the accounting purpose"},{"kind":"success","text":"You read SQL in logical order, repaired a join that excluded the needed records, corrected a transaction measure, and produced both an accounting report and an audit exception report."},{"kind":"subheader","text":"What changed in the report logic"},{"kind":"html","text":"<div class=\"logic-grid\">\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">PRESERVE THE POPULATION</div>\n            <h4>INNER JOIN → LEFT JOIN</h4>\n            <p>The original join removed orders without payments before the NULL test could examine them. The repaired join keeps every order and exposes unmatched payment fields as NULL.</p>\n          </section>\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">MEASURE THE TRANSACTION</div>\n            <h4>StandardPrice → ActualUnitPrice</h4>\n            <p>The master-data price is a benchmark, not proof of the historical exchange. The order-line price records what the customer was actually charged.</p>\n          </section>\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">MATCH THE PURPOSE</div>\n            <h4>Rows → accounting evidence</h4>\n            <p>A sales report summarizes the full population. An audit query isolates exceptions for follow-up. Neither output becomes evidence until its fields and completeness fit the question.</p>\n          </section>\n        </div>"},{"kind":"subheader","text":"The reasoning chain"},{"kind":"markdown","text":"FROM and JOIN determine which records can reach the result. WHERE then filters those candidate rows. GROUP BY and aggregate functions determine the level of summarization. SELECT names the fields and calculations displayed to the user. A query may run without an error and still answer the wrong accounting question."},{"kind":"html","text":"<div class=\"principle\"><strong>Audit boundary</strong> SQL identifies a population or exception. The accountant still has to decide whether the data are complete, whether the fields mean what the report assumes, and what evidence would resolve each exception.</div>"},{"kind":"subheader","text":"The same normalized structure supports each question"},{"kind":"html","text":"<div class=\"schema-key\"><span>CustomerID</span> Primary key field</div><div class=\"schema-grid\"><section class=\"schema-table\"><h4>Customers</h4><div class=\"schema-field primary-key\">CustomerID</div><div class=\"schema-field\">CustomerName</div><div class=\"schema-field\">CustomerCity</div></section><section class=\"schema-table\"><h4>Orders</h4><div class=\"schema-field primary-key\">OrderID</div><div class=\"schema-field\">OrderDate</div><div class=\"schema-field\">CustomerID</div><div class=\"schema-field\">OrderStatus</div></section><section class=\"schema-table\"><h4>Products</h4><div class=\"schema-field primary-key\">ProductID</div><div class=\"schema-field\">ProductName</div><div class=\"schema-field\">StandardPrice</div></section><section class=\"schema-table\"><h4>OrderLines</h4><div class=\"schema-field primary-key\">OrderLineID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">ProductID</div><div class=\"schema-field\">Quantity</div><div class=\"schema-field\">ActualUnitPrice</div></section><section class=\"schema-table\"><h4>Payments</h4><div class=\"schema-field primary-key\">PaymentID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">PaymentDate</div><div class=\"schema-field\">Amount</div></section></div>"},{"kind":"html","text":"<div class=\"principle\"><strong>Why the structure matters</strong> Primary and foreign keys let the query reconstruct the order-to-cash process without duplicating facts. The reporting purpose then determines which relationships, filters, calculations, and level of summarization belong in the result.</div>"},{"kind":"metric","label":"Investigation stages","value":"4 of 4"},{"kind":"metric","label":"Reports built","value":"2 of 2"},{"kind":"metric","label":"Revisions","value":0}],"wrong":[{"kind":"html","text":"<div class=\"eyebrow\">Investigation complete</div>"},{"kind":"header","text":"A correct query must match both the database structure and the accounting purpose"},{"kind":"success","text":"You read SQL in logical order, repaired a join that excluded the needed records, corrected a transaction measure, and produced both an accounting report and an audit exception report."},{"kind":"subheader","text":"What changed in the report logic"},{"kind":"html","text":"<div class=\"logic-grid\">\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">PRESERVE THE POPULATION</div>\n            <h4>INNER JOIN → LEFT JOIN</h4>\n            <p>The original join removed orders without payments before the NULL test could examine them. The repaired join keeps every order and exposes unmatched payment fields as NULL.</p>\n          </section>\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">MEASURE THE TRANSACTION</div>\n            <h4>StandardPrice → ActualUnitPrice</h4>\n            <p>The master-data price is a benchmark, not proof of the historical exchange. The order-line price records what the customer was actually charged.</p>\n          </section>\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">MATCH THE PURPOSE</div>\n            <h4>Rows → accounting evidence</h4>\n            <p>A sales report summarizes the full population. An audit query isolates exceptions for follow-up. Neither output becomes evidence until its fields and completeness fit the question.</p>\n          </section>\n        </div>"},{"kind":"subheader","text":"The reasoning chain"},{"kind":"markdown","text":"FROM and JOIN determine which records can reach the result. WHERE then filters those candidate rows. GROUP BY and aggregate functions determine the level of summarization. SELECT names the fields and calculations displayed to the user. A query may run without an error and still answer the wrong accounting question."},{"kind":"html","text":"<div class=\"principle\"><strong>Audit boundary</strong> SQL identifies a population or exception. The accountant still has to decide whether the data are complete, whether the fields mean what the report assumes, and what evidence would resolve each exception.</div>"},{"kind":"subheader","text":"The same normalized structure supports each question"},{"kind":"html","text":"<div class=\"schema-key\"><span>CustomerID</span> Primary key field</div><div class=\"schema-grid\"><section class=\"schema-table\"><h4>Customers</h4><div class=\"schema-field primary-key\">CustomerID</div><div class=\"schema-field\">CustomerName</div><div class=\"schema-field\">CustomerCity</div></section><section class=\"schema-table\"><h4>Orders</h4><div class=\"schema-field primary-key\">OrderID</div><div class=\"schema-field\">OrderDate</div><div class=\"schema-field\">CustomerID</div><div class=\"schema-field\">OrderStatus</div></section><section class=\"schema-table\"><h4>Products</h4><div class=\"schema-field primary-key\">ProductID</div><div class=\"schema-field\">ProductName</div><div class=\"schema-field\">StandardPrice</div></section><section class=\"schema-table\"><h4>OrderLines</h4><div class=\"schema-field primary-key\">OrderLineID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">ProductID</div><div class=\"schema-field\">Quantity</div><div class=\"schema-field\">ActualUnitPrice</div></section><section class=\"schema-table\"><h4>Payments</h4><div class=\"schema-field primary-key\">PaymentID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">PaymentDate</div><div class=\"schema-field\">Amount</div></section></div>"},{"kind":"html","text":"<div class=\"principle\"><strong>Why the structure matters</strong> Primary and foreign keys let the query reconstruct the order-to-cash process without duplicating facts. The reporting purpose then determines which relationships, filters, calculations, and level of summarization belong in the result.</div>"},{"kind":"metric","label":"Investigation stages","value":"4 of 4"},{"kind":"metric","label":"Reports built","value":"2 of 2"},{"kind":"metric","label":"Revisions","value":0}],"correct":[{"kind":"html","text":"<div class=\"eyebrow\">Investigation complete</div>"},{"kind":"header","text":"A correct query must match both the database structure and the accounting purpose"},{"kind":"success","text":"You read SQL in logical order, repaired a join that excluded the needed records, corrected a transaction measure, and produced both an accounting report and an audit exception report."},{"kind":"subheader","text":"What changed in the report logic"},{"kind":"html","text":"<div class=\"logic-grid\">\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">PRESERVE THE POPULATION</div>\n            <h4>INNER JOIN → LEFT JOIN</h4>\n            <p>The original join removed orders without payments before the NULL test could examine them. The repaired join keeps every order and exposes unmatched payment fields as NULL.</p>\n          </section>\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">MEASURE THE TRANSACTION</div>\n            <h4>StandardPrice → ActualUnitPrice</h4>\n            <p>The master-data price is a benchmark, not proof of the historical exchange. The order-line price records what the customer was actually charged.</p>\n          </section>\n          <section class=\"logic-card\">\n            <div class=\"logic-label\">MATCH THE PURPOSE</div>\n            <h4>Rows → accounting evidence</h4>\n            <p>A sales report summarizes the full population. An audit query isolates exceptions for follow-up. Neither output becomes evidence until its fields and completeness fit the question.</p>\n          </section>\n        </div>"},{"kind":"subheader","text":"The reasoning chain"},{"kind":"markdown","text":"FROM and JOIN determine which records can reach the result. WHERE then filters those candidate rows. GROUP BY and aggregate functions determine the level of summarization. SELECT names the fields and calculations displayed to the user. A query may run without an error and still answer the wrong accounting question."},{"kind":"html","text":"<div class=\"principle\"><strong>Audit boundary</strong> SQL identifies a population or exception. The accountant still has to decide whether the data are complete, whether the fields mean what the report assumes, and what evidence would resolve each exception.</div>"},{"kind":"subheader","text":"The same normalized structure supports each question"},{"kind":"html","text":"<div class=\"schema-key\"><span>CustomerID</span> Primary key field</div><div class=\"schema-grid\"><section class=\"schema-table\"><h4>Customers</h4><div class=\"schema-field primary-key\">CustomerID</div><div class=\"schema-field\">CustomerName</div><div class=\"schema-field\">CustomerCity</div></section><section class=\"schema-table\"><h4>Orders</h4><div class=\"schema-field primary-key\">OrderID</div><div class=\"schema-field\">OrderDate</div><div class=\"schema-field\">CustomerID</div><div class=\"schema-field\">OrderStatus</div></section><section class=\"schema-table\"><h4>Products</h4><div class=\"schema-field primary-key\">ProductID</div><div class=\"schema-field\">ProductName</div><div class=\"schema-field\">StandardPrice</div></section><section class=\"schema-table\"><h4>OrderLines</h4><div class=\"schema-field primary-key\">OrderLineID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">ProductID</div><div class=\"schema-field\">Quantity</div><div class=\"schema-field\">ActualUnitPrice</div></section><section class=\"schema-table\"><h4>Payments</h4><div class=\"schema-field primary-key\">PaymentID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">PaymentDate</div><div class=\"schema-field\">Amount</div></section></div>"},{"kind":"html","text":"<div class=\"principle\"><strong>Why the structure matters</strong> Primary and foreign keys let the query reconstruct the order-to-cash process without duplicating facts. The reporting purpose then determines which relationships, filters, calculations, and level of summarization belong in the result.</div>"},{"kind":"metric","label":"Investigation stages","value":"4 of 4"},{"kind":"metric","label":"Reports built","value":"2 of 2"},{"kind":"metric","label":"Revisions","value":0}]}],"groups":[{"stage":1,"id":"reading","key":"r","fields":[{"id":"source","answer":"FROM and JOIN","options":["SELECT","FROM and JOIN","WHERE","ORDER BY"],"widget":{"kind":"radio","label":"Which clauses assemble the rows before filtering?","options":["ORDER BY","SELECT","WHERE","FROM and JOIN"],"key":"widget_si_read_source","help":null},"feedback":{"SELECT":{"correct":false,"message":"Hint: Separate the written order from the database's logical work. Which clauses identify the starting rows and connect related tables before filtering?","label":"Which clauses assemble the rows before filtering?"},"FROM and JOIN":{"correct":true,"message":"FROM identifies the starting table, and JOIN adds matching rows from related tables.","label":"Which clauses assemble the rows before filtering?"},"WHERE":{"correct":false,"message":"Hint: Filtering can occur only after candidate rows exist. Look for the clauses that establish those rows.","label":"Which clauses assemble the rows before filtering?"},"ORDER BY":{"correct":false,"message":"Hint: Sorting changes row sequence, not row membership. Trace where the row set is first assembled.","label":"Which clauses assemble the rows before filtering?"}}},{"id":"filter","answer":"WHERE","options":["SELECT","ON","WHERE","GROUP BY"],"widget":{"kind":"radio","label":"Which clause removes rows that do not satisfy the reporting condition?","options":["GROUP BY","ON","WHERE","SELECT"],"key":"widget_si_read_filter","help":null},"feedback":{"SELECT":{"correct":false,"message":"Hint: Displayed columns do not decide which rows survive. Look for the clause that evaluates a condition after the joins.","label":"Which clause removes rows that do not satisfy the reporting condition?"},"ON":{"correct":false,"message":"Hint: ON controls how tables match during a join. Which later clause tests the reporting condition for the assembled rows?","label":"Which clause removes rows that do not satisfy the reporting condition?"},"WHERE":{"correct":true,"message":"WHERE evaluates the condition after the row sources and joins have been established.","label":"Which clause removes rows that do not satisfy the reporting condition?"},"GROUP BY":{"correct":false,"message":"Hint: Grouping changes the level of summarization. Look for the clause that keeps or removes rows based on a condition.","label":"Which clause removes rows that do not satisfy the reporting condition?"}}},{"id":"output","answer":"SELECT expressions","options":["SELECT expressions","FROM","ON","WHERE"],"widget":{"kind":"radio","label":"Which part determines the columns displayed in the result?","options":["ON","SELECT expressions","FROM","WHERE"],"key":"widget_si_read_output","help":null},"feedback":{"SELECT expressions":{"correct":true,"message":"SELECT appears first in the written query, but it describes the final output columns.","label":"Which part determines the columns displayed in the result?"},"FROM":{"correct":false,"message":"Hint: FROM identifies the starting source, not the displayed columns. Which expressions define what appears in the result?","label":"Which part determines the columns displayed in the result?"},"ON":{"correct":false,"message":"Hint: ON defines how rows match between tables. Look at the part of the query that names the output fields.","label":"Which part determines the columns displayed in the result?"},"WHERE":{"correct":false,"message":"Hint: WHERE determines which rows qualify, not which columns are shown. Which part lists the result fields?","label":"Which part determines the columns displayed in the result?"}}}],"prefix":[{"kind":"html","text":"<div class=\"eyebrow\">Step 1</div>"},{"kind":"header","text":"Read the query in logical order"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Trace what the database must do with the query. SQL begins with SELECT when written, but the database must establish the row sources and joins before it can filter rows and shape the final output.</p>"},{"kind":"code","text":"SELECT c.CustomerName,\n       o.OrderID,\n       ol.Quantity * ol.ActualUnitPrice AS LineAmount\nFROM Customers AS c\nJOIN Orders AS o\n  ON o.CustomerID = c.CustomerID\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nWHERE o.OrderStatus = 'Fulfilled'\nORDER BY c.CustomerName, o.OrderID;"}],"tail":[{"kind":"button","label":"Continue to the missing-record case","key":null}],"check":"Check how the query works"},{"stage":2,"id":"missing","key":"m","fields":[{"id":"repair","answer":"Replace INNER JOIN Payments with LEFT JOIN Payments and keep WHERE p.PaymentID IS NULL","options":["Replace INNER JOIN Payments with LEFT JOIN Payments and keep WHERE p.PaymentID IS NULL","Delete the WHERE clause","Replace INNER JOIN Payments with CROSS JOIN Payments","Change IS NULL to IS NOT NULL"],"widget":{"kind":"radio","label":"1. Which repair matches the reporting purpose?","options":["Delete the WHERE clause","Replace INNER JOIN Payments with CROSS JOIN Payments","Change IS NULL to IS NOT NULL","Replace INNER JOIN Payments with LEFT JOIN Payments and keep WHERE p.PaymentID IS NULL"],"key":"widget_si_missing_repair","help":null},"feedback":{"Replace INNER JOIN Payments with LEFT JOIN Payments and keep WHERE p.PaymentID IS NULL":{"correct":true,"message":"A left join keeps every order, and unmatched payment columns become NULL for the WHERE test.","label":"How to repair the query"},"Delete the WHERE clause":{"correct":false,"message":"Hint: The report still needs a test that isolates missing matches, so removing the filter cannot identify unpaid orders. Focus on preserving unmatched orders before that test runs.","label":"How to repair the query"},"Replace INNER JOIN Payments with CROSS JOIN Payments":{"correct":false,"message":"Hint: Pairing every order with every payment would invent combinations rather than reveal a missing relationship. Consider which type of join can preserve an order with no match.","label":"How to repair the query"},"Change IS NULL to IS NOT NULL":{"correct":false,"message":"Hint: That condition describes rows with an existing payment identifier. The controller needs the opposite population.","label":"How to repair the query"}}},{"id":"cause","answer":"A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test","options":["A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test","Deleting WHERE is appropriate because the INNER JOIN already isolates orders without payments","A CROSS JOIN creates unmatched payment rows with NULL identifiers for each unpaid order","Testing IS NOT NULL retains the orders that have no matching payment record"],"widget":{"kind":"radio","label":"2. Which explanation best supports that repair?","options":["Testing IS NOT NULL retains the orders that have no matching payment record","A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test","A CROSS JOIN creates unmatched payment rows with NULL identifiers for each unpaid order","Deleting WHERE is appropriate because the INNER JOIN already isolates orders without payments"],"key":"widget_si_missing_cause","help":null},"feedback":{"A LEFT JOIN preserves every order; orders without a payment match receive NULL payment fields that WHERE can test":{"correct":true,"message":"The original inner join kept only orders that already had a payment match, so no surviving row could have a NULL PaymentID.","label":"Why that repair works"},"Deleting WHERE is appropriate because the INNER JOIN already isolates orders without payments":{"correct":false,"message":"Hint: Ask whether the current join can leave any surviving row without a payment match.","label":"Why that repair works"},"A CROSS JOIN creates unmatched payment rows with NULL identifiers for each unpaid order":{"correct":false,"message":"Hint: Creating every possible order-payment combination does not provide evidence of an unmatched row. Focus on what a missing match should look like in the joined result.","label":"Why that repair works"},"Testing IS NOT NULL retains the orders that have no matching payment record":{"correct":false,"message":"Hint: Check whether the proposed condition describes an existing payment or a missing one.","label":"Why that repair works"}}}],"prefix":[{"kind":"html","text":"<div class=\"eyebrow\">Step 2</div>"},{"kind":"header","text":"Find why the unpaid-order report returns nothing"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the repair that preserves the records the controller needs, then select the explanation that supports your repair.</p>"},{"kind":"markdown","text":"The controller expects the report to list orders with no payment record. The current query returns zero rows even though two orders have no related payment."},{"kind":"code","text":"SELECT o.OrderID, c.CustomerName\nFROM Orders AS o\nJOIN Customers AS c\n  ON c.CustomerID = o.CustomerID\nINNER JOIN Payments AS p\n  ON p.OrderID = o.OrderID\nWHERE p.PaymentID IS NULL;"}],"tail":[{"kind":"subheader","text":"Repaired query and result"},{"kind":"code","text":"SELECT o.OrderID, c.CustomerName\nFROM Orders AS o\nJOIN Customers AS c\n  ON c.CustomerID = o.CustomerID\nLEFT JOIN Payments AS p\n  ON p.OrderID = o.OrderID\nWHERE p.PaymentID IS NULL\nORDER BY o.OrderID;"},{"kind":"table","rows":[{"OrderID":"O5003","CustomerName":"Blue Ridge Design"},{"OrderID":"O5004","CustomerName":"Riverbend Health"}]},{"kind":"html","text":"<div class=\"principle\"><strong>Accounting interpretation</strong> No payment row means no payment record in this database. It does not prove the customer owes the full order amount unless the system also records partial payments, credits, write-offs, and timing consistently.</div>"},{"kind":"button","label":"Continue to the wrong-amount case","key":null}],"check":"Diagnose the missing rows"},{"stage":3,"id":"amount","key":"a","fields":[{"id":"field","answer":"ol.ActualUnitPrice","options":["ol.ActualUnitPrice","p.StandardPrice","p.StandardPrice * 0.90","ol.Quantity"],"widget":{"kind":"radio","label":"1. Which value should be multiplied by ol.Quantity in the ReportedSales expression?","options":["ol.ActualUnitPrice","ol.Quantity","p.StandardPrice * 0.90","p.StandardPrice"],"key":"widget_si_amount_field","help":null},"feedback":{"ol.ActualUnitPrice":{"correct":true,"message":"ActualUnitPrice is stored on each line because it is a historical transaction fact.","label":"Which field belongs in sales"},"p.StandardPrice":{"correct":false,"message":"Hint: Distinguish a product benchmark from the amount recorded on the individual order line.","label":"Which field belongs in sales"},"p.StandardPrice * 0.90":{"correct":false,"message":"Hint: A fixed percentage assumes every discount is identical. Look for the stored transaction-specific amount.","label":"Which field belongs in sales"},"ol.Quantity":{"correct":false,"message":"Hint: Quantity tells how many units were sold, but sales also needs the price recorded for that line.","label":"Which field belongs in sales"}}},{"id":"cause","answer":"ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line","options":["ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line","p.StandardPrice is master data, so it always equals the price charged on every historical order line","Multiplying p.StandardPrice by 0.90 reliably reconstructs every discount without using the stored transaction price","ol.Quantity alone represents sales because the related product table already contains a price"],"widget":{"kind":"radio","label":"2. Which explanation best supports that choice?","options":["p.StandardPrice is master data, so it always equals the price charged on every historical order line","Multiplying p.StandardPrice by 0.90 reliably reconstructs every discount without using the stored transaction price","ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line","ol.Quantity alone represents sales because the related product table already contains a price"],"key":"widget_si_amount_cause","help":null},"feedback":{"ol.ActualUnitPrice is the historical transaction fact that records what the customer was charged on each line":{"correct":true,"message":"StandardPrice is current master data and remains useful as a benchmark, but it does not prove what the customer was charged on an earlier transaction.","label":"Why that field is appropriate"},"p.StandardPrice is master data, so it always equals the price charged on every historical order line":{"correct":false,"message":"Hint: Master data can change and discounts can vary. Which record preserves what actually happened in the transaction?","label":"Why that field is appropriate"},"Multiplying p.StandardPrice by 0.90 reliably reconstructs every discount without using the stored transaction price":{"correct":false,"message":"Hint: A formula assumes the discount rather than reading the recorded exchange. Look for transaction-level evidence.","label":"Why that field is appropriate"},"ol.Quantity alone represents sales because the related product table already contains a price":{"correct":false,"message":"Hint: Units alone do not produce a dollar amount. Identify the line-level price needed with quantity.","label":"Why that field is appropriate"}}}],"prefix":[{"kind":"html","text":"<div class=\"eyebrow\">Step 3</div>"},{"kind":"header","text":"Find why the sales amount is overstated"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Choose the value that measures the historical exchange, then select the explanation that supports your choice.</p>"},{"kind":"markdown","text":"The query runs and every order appears, but discounted lines are valued at the standard price instead of the price the customer actually paid."},{"kind":"code","text":"SELECT o.OrderID,\n       SUM(ol.Quantity * p.StandardPrice) AS ReportedSales\nFROM Orders AS o\nJOIN OrderLines AS ol\n  ON ol.OrderID = o.OrderID\nJOIN Products AS p\n  ON p.ProductID = ol.ProductID\nGROUP BY o.OrderID\nORDER BY o.OrderID;"}],"tail":[{"kind":"html","text":"<div class=\"principle\"><strong>Correct measure</strong> Sales for each line are ol.Quantity × ol.ActualUnitPrice. p.StandardPrice remains useful for exception testing, but it is not the recorded exchange amount.</div>"},{"kind":"button","label":"Continue to the custom query","key":null}],"check":"Diagnose the amount"}],"routes":["Accounting report","Audit exception report"],"prompts":{"Accounting report":{"purpose":"Calculate total fulfilled-order sales by customer using the historical price charged.","required":"Return exactly these aliases: CustomerName and TotalSales. Include every customer with fulfilled orders."},"Audit exception report":{"purpose":"Identify order lines sold more than 10 percent below the product's standard price.","required":"Return these aliases: OrderLineID, OrderID, ProductName, ActualUnitPrice, StandardPrice, and DiscountPct."}},"schemaSQL":"BEGIN TRANSACTION;\nCREATE TABLE Customers (\n            CustomerID TEXT PRIMARY KEY,\n            CustomerName TEXT NOT NULL,\n            CustomerCity TEXT NOT NULL\n        );\nINSERT INTO \"Customers\" VALUES('C100','Blue Ridge Design','Dayton');\nINSERT INTO \"Customers\" VALUES('C200','Patterson Legal','Kettering');\nINSERT INTO \"Customers\" VALUES('C300','Riverbend Health','Oakwood');\nCREATE TABLE OrderLines (\n            OrderLineID TEXT PRIMARY KEY,\n            OrderID TEXT NOT NULL REFERENCES Orders(OrderID),\n            ProductID TEXT NOT NULL REFERENCES Products(ProductID),\n            Quantity INTEGER NOT NULL,\n            ActualUnitPrice REAL NOT NULL\n        );\nINSERT INTO \"OrderLines\" VALUES('OL01','O5001','P100',2,310.0);\nINSERT INTO \"OrderLines\" VALUES('OL02','O5001','P200',4,80.0);\nINSERT INTO \"OrderLines\" VALUES('OL03','O5002','P300',1,700.0);\nINSERT INTO \"OrderLines\" VALUES('OL04','O5003','P100',1,275.0);\nINSERT INTO \"OrderLines\" VALUES('OL05','O5003','P400',2,240.0);\nINSERT INTO \"OrderLines\" VALUES('OL06','O5004','P200',10,70.0);\nCREATE TABLE Orders (\n            OrderID TEXT PRIMARY KEY,\n            OrderDate TEXT NOT NULL,\n            CustomerID TEXT NOT NULL REFERENCES Customers(CustomerID),\n            OrderStatus TEXT NOT NULL\n        );\nINSERT INTO \"Orders\" VALUES('O5001','2026-09-03','C100','Fulfilled');\nINSERT INTO \"Orders\" VALUES('O5002','2026-09-04','C200','Fulfilled');\nINSERT INTO \"Orders\" VALUES('O5003','2026-09-06','C100','Fulfilled');\nINSERT INTO \"Orders\" VALUES('O5004','2026-09-08','C300','Fulfilled');\nCREATE TABLE Payments (\n            PaymentID TEXT PRIMARY KEY,\n            OrderID TEXT NOT NULL REFERENCES Orders(OrderID),\n            PaymentDate TEXT NOT NULL,\n            Amount REAL NOT NULL\n        );\nINSERT INTO \"Payments\" VALUES('PAY01','O5001','2026-09-10',940.0);\nINSERT INTO \"Payments\" VALUES('PAY02','O5002','2026-09-12',700.0);\nCREATE TABLE Products (\n            ProductID TEXT PRIMARY KEY,\n            ProductName TEXT NOT NULL,\n            StandardPrice REAL NOT NULL\n        );\nINSERT INTO \"Products\" VALUES('P100','Ergonomic Chair',325.0);\nINSERT INTO \"Products\" VALUES('P200','Desk Lamp',85.0);\nINSERT INTO \"Products\" VALUES('P300','Standing Desk',700.0);\nINSERT INTO \"Products\" VALUES('P400','Filing Cabinet',240.0);\nCOMMIT;","customPrefix":[{"kind":"html","text":"<div class=\"eyebrow\">Step 4</div>"},{"kind":"header","text":"Build two queries for two accounting purposes"},{"kind":"html","text":"<p class=\"lead\"><strong>Your task:</strong> Write both queries below. Each editor is checked independently, and any executable query will display its output so you can compare the result with the stated purpose and revise.</p>"},{"kind":"subheader","text":"Available tables and fields"},{"kind":"html","text":"<div class=\"schema-key\"><span>CustomerID</span> Primary key field</div><div class=\"schema-grid\"><section class=\"schema-table\"><h4>Customers</h4><div class=\"schema-field primary-key\">CustomerID</div><div class=\"schema-field\">CustomerName</div><div class=\"schema-field\">CustomerCity</div></section><section class=\"schema-table\"><h4>Orders</h4><div class=\"schema-field primary-key\">OrderID</div><div class=\"schema-field\">OrderDate</div><div class=\"schema-field\">CustomerID</div><div class=\"schema-field\">OrderStatus</div></section><section class=\"schema-table\"><h4>Products</h4><div class=\"schema-field primary-key\">ProductID</div><div class=\"schema-field\">ProductName</div><div class=\"schema-field\">StandardPrice</div></section><section class=\"schema-table\"><h4>OrderLines</h4><div class=\"schema-field primary-key\">OrderLineID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">ProductID</div><div class=\"schema-field\">Quantity</div><div class=\"schema-field\">ActualUnitPrice</div></section><section class=\"schema-table\"><h4>Payments</h4><div class=\"schema-field primary-key\">PaymentID</div><div class=\"schema-field\">OrderID</div><div class=\"schema-field\">PaymentDate</div><div class=\"schema-field\">Amount</div></section></div>"}],"expectedAccounting":{"Blue Ridge Design":1695.0,"Patterson Legal":700.0,"Riverbend Health":700.0},"expectedAudit":{"OL04":["O5003","Ergonomic Chair",275.0,325.0,15.384615],"OL06":["O5004","Desk Lamp",70.0,85.0,17.647059]}};
